// Zprávy ze tří RSS za posledních 15 dní → zadání pro Clauda.
// Zdroj, který zrovna neodpověděl, se přeskočí (RSS uzly mají „pokračovat při chybě“).
const ZDROJE = [
  { uzel: 'Nacist_Mesec', nazev: 'Měšec.cz' },
  { uzel: 'Nacist_Penize', nazev: 'Peníze.cz' },
  { uzel: 'Nacist_CT24', nazev: 'ČT24' },
];
const OD = Date.now() - 15 * 24 * 60 * 60 * 1000;
const bezHtml = (t) => String(t ?? '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
// Odkaz bez sledovacích parametrů (utm_…). Schválně bez objektu URL –
// v sandboxu Code uzlu n8n není a každá zpráva by se tím vyřadila.
const cistyOdkaz = (url) => {
  const odkaz = String(url ?? '').replace(/&amp;/g, '&').trim();
  if (!/^https?:\/\//i.test(odkaz)) return null;
  const [zaklad, dotaz = ''] = odkaz.split('#')[0].split('?');
  const parametry = dotaz.split('&').filter((p) => p && !/^utm_/i.test(p));
  return parametry.length ? `${zaklad}?${parametry.join('&')}` : zaklad;
};

const zpravy = [];
const pocty = [];
for (const zdroj of ZDROJE) {
  let polozky = [];
  try { polozky = $(zdroj.uzel).all(); } catch (e) { pocty.push(`${zdroj.nazev} neodpověděl`); continue; }
  let pouzito = 0;
  for (const { json: j } of polozky) {
    const datum = new Date(j.isoDate || j.pubDate || 0);
    const odkaz = cistyOdkaz(j.link);
    if (!j.title || !odkaz || isNaN(datum.getTime()) || datum.getTime() < OD) continue;
    zpravy.push({
      zdroj: zdroj.nazev,
      titulek: bezHtml(j.title),
      popis: bezHtml(j.contentSnippet || j.content || j.description).slice(0, 400),
      odkaz,
      datum: datum.toISOString().slice(0, 10),
    });
    pouzito++;
  }
  pocty.push(`${zdroj.nazev} ${pouzito} z ${polozky.length}`);
}
zpravy.sort((a, b) => b.datum.localeCompare(a.datum));
const vybrane = zpravy.slice(0, 45);
if (vybrane.length < 3) {
  throw new Error(`Za posledních 15 dní jsou jen ${vybrane.length} zprávy – článek se tentokrát nepíše. Použito: ${pocty.join(', ')}.`);
}

const seznam = vybrane
  .map((z, i) => `${i + 1}. [${z.zdroj}] ${z.datum} – ${z.titulek}\n${z.popis}\n${z.odkaz}`)
  .join('\n\n');

const SYSTEM = "Píšeš krátké články do sekce Novinky na webu poradcedokapsy.cz. Autorem je Jakub Jevčák, finanční poradce, který lidem pomáhá s hypotékou, pojištěním, spořením a investicemi. Čtenáři jsou běžné domácnosti, ne odborníci.\n\nÚkol: Z přiložených zpráv za poslední dva týdny vyber jedno až tři témata, která se nejvíc dotýkají peněz běžných domácností (hypotéky a úroky, pojištění, spoření a penzijní spoření, investice, ceny a inflace, daně a státní podpora). Napiš o nich jeden článek: co se stalo a co to znamená pro čtenáře.\n\nPravidla:\n- Piš česky, srozumitelně a krátkými větami, čtenáři vykej. Odborný pojem vysvětli.\n- Vycházej jen z údajů ve zprávách. Nepřidávej čísla, data, jména ani tvrzení, která ve zprávách nejsou. Když něco nevíš jistě, nepiš to.\n- Zprávy nepřebírej doslova, napiš vlastní text.\n- Nedávej investiční doporučení: nedoporučuj konkrétní produkt, banku, pojišťovnu, fond ani akcii a nepiš, co si má čtenář koupit nebo prodat. Můžeš napsat, na co se zaměřit nebo co si ověřit ve vlastní smlouvě.\n- Žádné sliby výnosů ani úspor, žádné superlativy, vykřičníky ani emoji. Nepoužívej slova „nezávislý“ a „nezávisle“.\n\nFormát odpovědi (JSON podle schématu):\n- titulek: věcný, do 90 znaků, bez lákání na kliknutí.\n- perex: jedna až dvě věty do 250 znaků, o čem článek je.\n- obsah: 250 až 450 slov. Odstavce odděl prázdným řádkem. Mezititulek dej na samostatný řádek začínající „## “, odrážky začínají „- “. Žádné jiné formátování: bez tučného písma, odkazů a HTML.\n- zdroje: zprávy, ze kterých článek vychází – název média a přesná adresa článku ze seznamu.";
const SCHEMA = {
  "type": "object",
  "properties": {
    "titulek": {
      "type": "string"
    },
    "perex": {
      "type": "string"
    },
    "obsah": {
      "type": "string"
    },
    "zdroje": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "nazev": {
            "type": "string"
          },
          "url": {
            "type": "string"
          }
        },
        "required": [
          "nazev",
          "url"
        ],
        "additionalProperties": false
      }
    }
  },
  "required": [
    "titulek",
    "perex",
    "obsah",
    "zdroje"
  ],
  "additionalProperties": false
};

return [{
  json: {
    odkazy: vybrane.map((z) => z.odkaz),
    pozadavek: {
      model: 'claude-opus-5-5',
      max_tokens: 16000,
      // Když bezpečnostní filtr požadavek odmítne, API ho samo zopakuje na doporučeném záložním modelu.
      fallbacks: 'default',
      output_config: { effort: 'high', format: { type: 'json_schema', schema: SCHEMA } },
      system: SYSTEM,
      messages: [{ role: 'user', content: `Zprávy z posledních dvou týdnů:\n\n${seznam}` }],
    },
  },
}];

// Odpověď Clauda → článek a text e-mailu ke schválení.
const odpoved = $input.first().json;
if (odpoved.stop_reason === 'refusal') throw new Error('Claude článek odmítl napsat (refusal). Zkuste workflow spustit znovu.');
if (odpoved.stop_reason === 'max_tokens') throw new Error('Článek se nevešel do limitu odpovědi.');

// Model s myšlením vrací před textem i bloky „thinking“ – článek je v bloku typu text.
const text = (odpoved.content || []).find((b) => b.type === 'text')?.text;
if (!text) throw new Error('V odpovědi chybí text článku.');
const clanek = JSON.parse(text);
for (const pole of ['titulek', 'perex', 'obsah']) {
  if (!String(clanek[pole] || '').trim()) throw new Error(`Článku chybí ${pole}.`);
}

// Zdroje: jen adresy, které byly opravdu v zadání (vymyšlená na web nesmí),
// a s titulkem článku z RSS – „ČT24“ dvakrát pod sebou čtenáři nic neřekne.
// Odkazy se čistí stejně jako v Pripravit_zpravy, jinak by se nespárovaly.
const ZDROJE = [
  { uzel: 'Nacist_Mesec', nazev: 'Měšec.cz' },
  { uzel: 'Nacist_Penize', nazev: 'Peníze.cz' },
  { uzel: 'Nacist_CT24', nazev: 'ČT24' },
];
const bezHtml = (t) => String(t ?? '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const cistyOdkaz = (url) => {
  const odkaz = String(url ?? '').replace(/&amp;/g, '&').trim();
  if (!/^https?:\/\//i.test(odkaz)) return null;
  const [zaklad, dotaz = ''] = odkaz.split('#')[0].split('?');
  const parametry = dotaz.split('&').filter((p) => p && !/^utm_/i.test(p));
  return parametry.length ? `${zaklad}?${parametry.join('&')}` : zaklad;
};
const nazvy = new Map();
for (const zdroj of ZDROJE) {
  let polozky = [];
  try { polozky = $(zdroj.uzel).all(); } catch (e) { continue; }
  for (const { json: j } of polozky) {
    const odkaz = cistyOdkaz(j.link);
    if (odkaz && j.title) nazvy.set(odkaz, `${zdroj.nazev}: ${bezHtml(j.title)}`);
  }
}
const povolene = new Set($('Pripravit_zpravy').first().json.odkazy);
const videne = new Set();
clanek.zdroje = (clanek.zdroje || [])
  .filter((z) => povolene.has(z.url) && !videne.has(z.url) && videne.add(z.url))
  .map((z) => ({ nazev: nazvy.get(z.url) || z.nazev, url: z.url }))
  .slice(0, 10);

// E-mail se schválením je prostý text (n8n HTML escapuje) – mezititulky velkými písmeny.
const obsahEmailu = clanek.obsah.replace(/^#{2,3}\s+(.*)$/gm, (_, t) => t.toUpperCase());
const zdroje = clanek.zdroje.map((z) => `- ${z.nazev}: ${z.url}`).join('\n') || '- (bez zdrojů)';
const zprava = [
  'Nový článek do Novinek na poradcedokapsy.cz čeká na schválení.',
  '',
  clanek.titulek,
  '',
  clanek.perex,
  '',
  obsahEmailu,
  '',
  'Zdroje:',
  zdroje,
  '',
  'Zveřejnit = článek se hned objeví na webu. Když do 7 dní nerozhodnete, zahodí se.',
].join('\n');

return [{ json: { clanek, predmet: `Ke schválení: ${clanek.titulek}`, zprava } }];
